INSERT INTO feature VALUES('second-order-rules','rules','Second-order rules','rule-coincidence','partial','notable',NULL,'A rule over a binding operation applies a bound variable to one argument per variable it binds (`t(u)`, read as its instantiation), abstracts the variables a port binds (`bind x . t`, named at a port of their sort) and, on a left side, applies a bound variable to the variables abstracted above it as a pattern its right side instantiates; the abstraction at a `pi+` port is the port''s binding field, kept in the Theory value as `Bind` and its variable as `Bvar`, apart from an atom''s abstraction, so a variable crossing it needs no freshness condition and a condition naming its variable is refused as naming no atom; a rule writes one binder per port, two at one port waiting on the grammar (#2347). It is sorted at its binders by check_desc and oriented by HORPO''s metavariable case read up to η, an instantiation at a value of a sort no operation returns needing no cover. Its critical pairs are found by pattern unification and joined in the second-order reading, where a rule''s variable stands for a term over the names its pattern applies it to and an instance substitutes for them; a pair that parts is refused, never completed (#2361), in the producer and the kernel alike. An inspected call of a block holding such a rule is normalized in the kernel''s second-order reading, each rule stated under no row fired by matching its pattern and substituting its instance, a call''s `bind x . t` at a binding port read as the port''s field; the model derivation states the binding operation (`signature-models`) but not yet a law relating a term at its port (#1324).','theory-levitation theory-computads surface-lowering kernel-term','corpus/model/desc/second-order-rules.gandr corpus/pathological/desc/second-order-rules.gandr corpus/model/desc/relative-monad.gandr corpus/pathological/desc/relative-monad.gandr corpus/model/effects/state.gandr corpus/pathological/effects/state.gandr corpus/model/desc/binding-field.gandr corpus/pathological/desc/binding-field.gandr','corpus/ledger/features/second-order-rules.gandr','#1324 #1326 #2328 #2347 #2361');
